import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.CCCdsIgc.js";const h=JSON.parse('{"title":"消息通知","description":"","frontmatter":{},"headers":[],"relativePath":"guide/notices.md","filePath":"guide/notices.md"}'),i={name:"guide/notices.md"};function n(s,t,l,d,c,_){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="消息通知" tabindex="-1">消息通知 <a class="header-anchor" href="#消息通知" aria-label="Permalink to &quot;消息通知&quot;">​</a></h1><p>IT 会通过 FlyknitBuddy 发通知：系统升级、新功能介绍、停机维护、安全提醒、公司制度、培训活动、使用技巧等。</p><h2 id="在哪里看" tabindex="-1">在哪里看 <a class="header-anchor" href="#在哪里看" aria-label="Permalink to &quot;在哪里看&quot;">​</a></h2><ul><li>左下角你的名字旁边有个<strong>铃铛</strong>，红色数字是没读过的通知数；</li><li>点铃铛打开<strong>消息中心</strong>：「重要」的通知排在最上面，其余按日期分组；可以只看「未读」，也可以一键「全部已读」；</li><li>点一条打开详情。正文里可以有图片、视频、表格；链接和底部的按钮会用系统浏览器打开。</li></ul><p><strong>重要</strong>通知（比如安全提醒、停机通知）在你打开程序时会直接弹出来，点「知道了」就算读过，以后不再弹。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>看不到铃铛</strong>：服务端还没升级到支持通知的版本，等 IT 升级就有了。</li><li><strong>别的部门同事看到的通知我没有</strong>：通知可以只发给某些部门或某几台电脑，你只会看到发给你的。</li><li><strong>通知突然不见了</strong>：IT 撤回了，或者过了有效期（比如维护通知过了维护时间）。</li></ul>',7)])])}const g=a(i,[["render",n]]);export{h as __pageData,g as default};
